// Typed access to the static JSON data files.

import type { Course, Offering, RequirementGroup } from "../solver/types";
import coursesJson from "./courses.json";
import requirementsJson from "./requirements.json";
import metaJson from "./meta.json";
import sectionsJson from "./sections.json";

/** Generated by scripts/scrape-ucr.ts (see scripts/lib/termMeta.ts). */
export type TermMeta = {
  term: string;
  /** e.g. "Fall 2026" */
  termLabel: string;
  /** First/last day of classes, YYYY-MM-DD (America/Los_Angeles), from Banner's meeting dates. */
  termStart: string;
  termEnd: string;
  /** Date the schedule data was fetched from Banner, YYYY-MM-DD. */
  scrapedOn: string;
  /**
   * Weekdays with no classes (UCR academic calendar), YYYY-MM-DD. Hand-entered —
   * Banner doesn't publish them; scrape-ucr.ts keeps them across re-scrapes of the same term.
   */
  holidays: { date: string; name: string }[];
};

export const courses = coursesJson as Course[];
export const requirements = requirementsJson as RequirementGroup[];
export const offerings = sectionsJson as Offering[];
export const meta = metaJson as TermMeta;
